class ApiService { static const baseUrl='http://127.0.0.1:8000'; static const health='$baseUrl/health'; static const predictDisease='$baseUrl/predict-disease'; static const digitalTwin='$baseUrl/digital-twin'; static const history='$baseUrl/history'; static const simulateCameraCapture='$baseUrl/simulate-camera-capture'; static const simulateSensorUpdate='$baseUrl/simulate-sensor-update'; static String pump(String state)=>'$baseUrl/actuator/pump/$state'; static String imageUrl(String? p){if(p==null||p.isEmpty)return '';if(p.startsWith('http'))return p;return p.startsWith('/')?'$baseUrl$p':'$baseUrl/$p';}}
